// Generate blog post
const categories = ['nasa-news', 'space-facts', 'satellite-tutorials', 'astronomy-lessons'];
const topics = {
  'nasa-news': ['NASA Perseverance Rover discovers new evidence', 'James Webb Telescope reveals stunning images', 'SpaceX launches Falcon Heavy'],
  'space-facts': ['The ISS orbits Earth 16 times per day', 'There are over 5,000 active satellites'],
  'satellite-tutorials': ['How GPS satellites calculate your location', 'Why weather satellites orbit at 36,000 km'],
  'astronomy-lessons': ['How stars are born from gas clouds', 'What happens when a star dies']
};
const category = categories[Math.floor(Math.random() * categories.length)];
const title = topics[category][Math.floor(Math.random() * topics[category].length)];
const slug = title.toLowerCase().replace(/[^a-z0-9]+/g, '-');
const today = new Date().toISOString().split('T')[0];

return {
  json: {
    slug,
    title,
    excerpt: `Learn about ${title.toLowerCase()} and orbital mechanics.`,
    content: `# ${title}\n\n${title} is fascinating. Learn more with our [simulator](/simulator) and [formulas](/formulas-library).`,
    category,
    date: today,
    tags: ['space', 'orbital mechanics'],
    seoKeywords: 'space, orbital mechanics, NASA'
  }
};

// Generate daily topic
const categories = ['nasa', 'newton', 'quantum-physics', 'astrophysics'];
const topics = {
  'nasa': [{ title: 'International Space Station', icon: '🛰️', url: '/satellites', desc: 'Learn how the ISS orbits Earth.', keywords: ['ISS', 'NASA'] }],
  'newton': [{ title: 'Newton\'s Laws of Motion', icon: '⚖️', url: '/learn/newton', desc: 'Learn Newton\'s three laws.', keywords: ['Newton', 'physics'] }],
  'quantum-physics': [{ title: 'Quantum Mechanics', icon: '⚛️', url: '/research', desc: 'Introduction to quantum physics.', keywords: ['quantum', 'physics'] }],
  'astrophysics': [{ title: 'Black Holes', icon: '🕳️', url: '/research', desc: 'Learn about black holes.', keywords: ['black holes', 'astrophysics'] }]
};
const category = categories[Math.floor(Math.random() * categories.length)];
const topic = topics[category][0];
const today = new Date().toISOString().split('T')[0];

return {
  json: {
    id: `${category}-${today}`,
    date: today,
    title: topic.title,
    icon: topic.icon,
    category,
    description: topic.desc,
    learnMoreUrl: topic.url,
    keywords: topic.keywords
  }
};
